from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from oscar.core.loading import get_model

Basket = get_model('basket', 'Basket')
Voucher = get_model('voucher', 'Voucher')

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def apply_voucher_to_basket(request, basket_id):
    voucher_code = request.data.get('code')
    # Require that the basket is currently owned by request.user
    try:
        basket = Basket.objects.get(pk=basket_id, owner=request.user)
        voucher = Voucher.objects.get(code=voucher_code)
    except (Basket.DoesNotExist, Voucher.DoesNotExist):
        return Response({'error': 'Basket or voucher not found'}, status=status.HTTP_404_NOT_FOUND)

    basket.vouchers.add(voucher)
    return Response({'status': 'voucher applied', 'discount': voucher.name})
